def hidden_rule_fn(state):
    # Parse state into lists of particles
    particles = []
    for p in state:
        particles.append({'type': p['type'], 'x': p['x'], 'y': p['y']})

    # Helper: compute wovve_dist between two particles
    def wovve_dist(p1, p2):
        dx = abs(p1['x'] - p2['x'])
        dy = abs(p1['y'] - p2['y'])
        wrap_dx = min(dx, 8 - dx)
        wrap_dy = min(dy, 8 - dy)
        return wrap_dx**2 + wrap_dy

    # Helper: compute direction from p1 to p2 on torus, returns (dx, dy) each in {-1, 0, +1}
    def direction(p1, p2):
        dx = (p2['x'] - p1['x']) % 8
        dy = (p2['y'] - p1['y']) % 8
        # Determine direction for x
        if dx == 0:
            dir_x = 0
        elif dx <= 4:
            dir_x = 1
        else:
            dir_x = -1
        # Determine direction for y
        if dy == 0:
            dir_y = 0
        elif dy <= 4:
            dir_y = 1
        else:
            dir_y = -1
        return (dir_x, dir_y)

    # Separate PLEKTs and WOVVEs
    plekts = [p for p in particles if p['type'] == 'PLEKT']
    wovves = [p for p in particles if p['type'] == 'WOVVE']

    # Compute new positions
    next_particles = []

    # For PLEKTs: move toward nearest WOVVE
    for p in plekts:
        nearest = None
        min_dist = float('inf')
        for w in wovves:
            d = wovve_dist(p, w)
            if d < min_dist:
                min_dist = d
                nearest = w
        if nearest:
            dx, dy = direction(p, nearest)
            nx = (p['x'] + dx) % 8
            ny = (p['y'] + dy) % 8
            next_particles.append({'type': 'PLEKT', 'x': nx, 'y': ny})
        else:
            next_particles.append({'type': 'PLEKT', 'x': p['x'], 'y': p['y']})

    # For WOVVEs: move away from nearest PLEKT
    for p in wovves:
        nearest = None
        min_dist = float('inf')
        for pl in plekts:
            d = wovve_dist(p, pl)
            if d < min_dist:
                min_dist = d
                nearest = pl
        if nearest:
            dx, dy = direction(p, nearest)
            # Move away (reverse direction)
            nx = (p['x'] - dx) % 8
            ny = (p['y'] - dy) % 8
            next_particles.append({'type': 'WOVVE', 'x': nx, 'y': ny})
        else:
            next_particles.append({'type': 'WOVVE', 'x': p['x'], 'y': p['y']})

    # WOVVEs spawn at their anti-pole if unoccupied
    occupied = set()
    for p in next_particles:
        occupied.add((p['x'], p['y']))

    for w in wovves:
        anti_x = (w['x'] + 4) % 8
        anti_y = (w['y'] + 4) % 8
        if (anti_x, anti_y) not in occupied:
            next_particles.append({'type': 'WOVVE', 'x': anti_x, 'y': anti_y})
            occupied.add((anti_x, anti_y))

    return next_particles
